#!/usr/bin/env bash
# One registry of error codes, and the source files generated from it. A handler cannot return a
# code that is not in .agents/error-codes.tsv, because the type it uses is written from that file.
#
#   scripts/error-codes.sh            check the registry, and that the generated files are current
#   scripts/error-codes.sh --write    write the files named by the @emit lines
#   scripts/error-codes.sh --list     print code, status and message
set -uo pipefail
cd "$(git rev-parse --show-toplevel)"

reg="${ERROR_CODES_FILE:-.agents/error-codes.tsv}"
base_ref="${CHECK_BASE:-origin/main}"
mode="${1:-check}"
case "$mode" in check|--write|--list) ;; *) echo "usage: scripts/error-codes.sh [--write|--list]" >&2; exit 2 ;; esac
[ -f "$reg" ] || { echo "errors: $reg is missing. Copy it from the guidelines template." >&2; exit 1; }

# The codes every repository shares, and the only statuses an API of ours returns.
shared='invalid_request 400
unauthenticated 401
permission_denied 403
not_found 404
method_not_allowed 405
conflict 409
payload_too_large 413
unsupported_media_type 415
rate_limited 429
internal 500
upstream_failed 502
unavailable 503
timeout 504'
allowed="400 401 403 404 405 409 410 412 413 415 428 429 500 501 502 503 504 $(awk '$1 == "@allow-status" { print $2 }' "$reg" | tr '\n' ' ')"

rows() { grep -Ev '^[[:space:]]*(#|@|$)' "$1"; }
[ "$mode" = --list ] && { rows "$reg" | cut -f1-3; exit 0; }

fail=0
say() { echo "errors: $1"; fail=1; }

problems="$(rows "$reg" | awk -F'\t' -v allowed=" $allowed " '
  NF < 3 || NF > 4          { print "line \"" $0 "\" needs three tab-separated fields: code, status, message."; next }
  $1 !~ /^[a-z][a-z0-9]*(_[a-z0-9]+)*$/ || length($1) > 63 { print $1 ": a code is lower snake_case, at most 63 characters." }
  index(allowed, " " $2 " ") == 0 { print $1 ": status " $2 " is not in the standard table (docs/conventions.md). Use the closest one from it." }
  $3 !~ /^[A-Z].*\.$/       { print $1 ": the message is a sentence: capital first letter, full stop at the end." }
  $3 ~ /["\\]/              { print $1 ": the message must not contain a double quote or a backslash." }
  NF == 4 && $4 != "deprecated" { print $1 ": the fourth column can only be the word deprecated." }
  seen[$1]++                { print $1 ": listed twice. A code has one row and one status." }
')"
[ -n "$problems" ] && while IFS= read -r p; do say "$p"; done <<<"$problems"

while read -r code status; do
  rows "$reg" | awk -F'\t' -v c="$code" -v s="$status" '$1 == c && $2 == s { ok = 1 } END { exit !ok }' \
    || say "$code: the shared code $code ($status) is missing or changed. Every repository has it with this status; restore the row."
done <<<"$shared"

# A code that has reached the main branch is published. It may gain "deprecated"; nothing else.
if base="$(git merge-base HEAD "$base_ref" 2>/dev/null)" && git cat-file -e "$base:$reg" 2>/dev/null; then
  while IFS=$'\t' read -r code status _; do
    rows "$reg" | awk -F'\t' -v c="$code" -v s="$status" '$1 == c && $2 == s { ok = 1 } END { exit !ok }' \
      || say "$code: was $status on the main branch and is now gone or has another status. Clients depend on it. Restore the row, and write deprecated in a fourth column if it is no longer returned."
  done < <(git show "$base:$reg" | grep -Ev '^[[:space:]]*(#|@|$)')
fi

header="Generated by scripts/error-codes.sh from $reg. Do not edit this file:
add a row to the registry and run scripts/error-codes.sh --write."

emit() {  # language -> the file's text on stdout
  case "$1" in
    ts)
      printf '%s\n' "$header" | sed 's|^|// |'
      rows "$reg" | awk -F'\t' '
        BEGIN { print "// prettier-ignore\n// biome-ignore format: generated\nexport const ERROR_CODES = {" }
        { printf "  %s: { status: %s, message: \"%s\" },\n", $1, $2, $3 }
        END { print "} as const;\n\nexport type ErrorCode = keyof typeof ERROR_CODES;" }' ;;
    rust)
      printf '%s\n' "$header" | sed 's|^|// |'
      rows "$reg" | awk -F'\t' '
        function pascal(s,   n, i, parts, out) { n = split(s, parts, "_"); out = ""
          for (i = 1; i <= n; i++) out = out toupper(substr(parts[i], 1, 1)) substr(parts[i], 2); return out }
        { name[NR] = pascal($1); code[NR] = $1; status[NR] = $2; message[NR] = $3 }
        END {
          print "\n/// Every error code this API can return.\n#[rustfmt::skip]\n#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]\npub enum ErrorCode {"
          for (i = 1; i <= NR; i++) print "    " name[i] ","
          print "}\n\n#[rustfmt::skip]\nimpl ErrorCode {\n    /// All codes, in registry order.\n    pub const ALL: &[ErrorCode] = &["
          for (i = 1; i <= NR; i++) print "        ErrorCode::" name[i] ","
          print "    ];\n\n    /// The string sent to clients.\n    #[must_use]\n    pub const fn as_str(self) -> &'"'"'static str {\n        match self {"
          for (i = 1; i <= NR; i++) print "            Self::" name[i] " => \"" code[i] "\","
          print "        }\n    }\n\n    /// The HTTP status this code is always sent with.\n    #[must_use]\n    #[allow(clippy::match_same_arms, reason = \"one arm per code, generated\")]\n    pub const fn status(self) -> u16 {\n        match self {"
          for (i = 1; i <= NR; i++) print "            Self::" name[i] " => " status[i] ","
          print "        }\n    }\n\n    /// The default message for the code.\n    #[must_use]\n    #[allow(clippy::match_same_arms, reason = \"one arm per code, generated\")]\n    pub const fn message(self) -> &'"'"'static str {\n        match self {"
          for (i = 1; i <= NR; i++) print "            Self::" name[i] " => \"" message[i] "\","
          print "        }\n    }\n}"
        }' ;;
    python)
      printf '%s\n' "$header" | sed 's|^|# |'
      rows "$reg" | awk -F'\t' '
        BEGIN { print "# fmt: off\n# ruff: noqa\n\n# code -> (HTTP status, default message)\nERROR_CODES: dict[str, tuple[int, str]] = {" }
        { printf "    \"%s\": (%s, \"%s\"),\n", $1, $2, $3 }
        END { print "}" }' ;;
    *) return 1 ;;
  esac
}

targets=0
while read -r _ lang path; do
  targets=$((targets + 1))
  out="$(emit "$lang")" || { say "@emit $lang $path: the language must be ts, rust or python."; continue; }
  if [ "$mode" = --write ]; then
    [ "$fail" -eq 0 ] || continue
    mkdir -p "$(dirname "$path")" && printf '%s\n' "$out" > "$path" && echo "errors: wrote $path"
  elif [ ! -f "$path" ] || [ "$(cat "$path")" != "$out" ]; then
    say "$path is out of date with $reg. Run scripts/error-codes.sh --write and commit the result."
  fi
done < <(grep -E '^@emit[[:space:]]' "$reg")

[ "$fail" -eq 0 ] || exit 1
[ "$mode" = --write ] && [ "$targets" -eq 0 ] && echo "errors: no @emit line in $reg, so nothing was written. Add one for each language that returns errors."
echo "errors: ok ($(rows "$reg" | wc -l | tr -d ' ') codes, $targets generated file(s))"
